"""JSON Lines 数据加载与校验。

每行必须是一个 JSON 对象，且恰好包含以下字段：

- ``tx_hash``：非空字符串，全文件唯一
- ``block_number``：非负整数
- ``timestamp``：非负整数（UTC 秒）
- ``from_address`` / ``to_address`` / ``method``：非空字符串
- ``amount``：非负十进制整数字符串（如 ``"1000"``，不接受数字类型、负号、小数点）

任何解析或校验失败抛 :class:`~tx_indexer.errors.InvalidTransactionError`，
``input_line`` 为 1 起始的物理行号；``tx_hash`` 冲突抛
:class:`~tx_indexer.errors.DuplicateTransactionError`。
"""

import json
import re

from .errors import DuplicateTransactionError, InvalidTransactionError

_FIELDS = (
    "tx_hash",
    "block_number",
    "timestamp",
    "from_address",
    "to_address",
    "method",
    "amount",
)
_AMOUNT_RE = re.compile(r"[0-9]+")


def _is_nonneg_int(value):
    # bool 是 int 的子类，必须显式排除
    return isinstance(value, int) and not isinstance(value, bool) and value >= 0


def _is_nonempty_text(value):
    return isinstance(value, str) and value.strip() != ""


def parse_record(obj, line_no):
    """把一个已解析的 JSON 值校验并转换为内部记录。"""
    if not isinstance(obj, dict):
        raise InvalidTransactionError("每行必须是 JSON 对象", line_no)

    keys = set(obj.keys())
    missing = [f for f in _FIELDS if f not in keys]
    if missing:
        raise InvalidTransactionError(
            "缺少字段：%s" % ", ".join(missing), line_no
        )
    extra = sorted(keys - set(_FIELDS))
    if extra:
        raise InvalidTransactionError(
            "存在未定义字段：%s" % ", ".join(extra), line_no
        )

    tx_hash = obj["tx_hash"]
    if not _is_nonempty_text(tx_hash):
        raise InvalidTransactionError("tx_hash 必须为非空字符串", line_no)

    block_number = obj["block_number"]
    if not _is_nonneg_int(block_number):
        raise InvalidTransactionError(
            "block_number 必须为非负整数", line_no
        )

    timestamp = obj["timestamp"]
    if not _is_nonneg_int(timestamp):
        raise InvalidTransactionError(
            "timestamp 必须为非负 UTC 秒整数", line_no
        )

    for name in ("from_address", "to_address", "method"):
        if not _is_nonempty_text(obj[name]):
            raise InvalidTransactionError(
                "%s 必须为非空字符串" % name, line_no
            )

    amount = obj["amount"]
    if not isinstance(amount, str) or _AMOUNT_RE.fullmatch(amount) is None:
        raise InvalidTransactionError(
            "amount 必须为非负十进制整数字符串", line_no
        )

    return {
        "tx_hash": tx_hash,
        "block_number": block_number,
        "timestamp": timestamp,
        "from_address": obj["from_address"],
        "to_address": obj["to_address"],
        "method": obj["method"],
        "amount": amount,
    }


def load_lines(lines):
    """从行迭代器加载记录，返回内部记录列表。"""
    records = []
    seen = set()
    for line_no, raw in enumerate(lines, start=1):
        text = raw.strip()
        if text == "":
            raise InvalidTransactionError("空行不是合法记录", line_no)
        try:
            obj = json.loads(text)
        except json.JSONDecodeError as exc:
            raise InvalidTransactionError(
                "JSON 解析失败：%s" % exc.msg, line_no
            ) from exc

        record = parse_record(obj, line_no)

        if record["tx_hash"] in seen:
            raise DuplicateTransactionError(
                "tx_hash 冲突：%s" % record["tx_hash"], line_no
            )
        seen.add(record["tx_hash"])
        records.append(record)
    return records


def load_file(path):
    """从 JSON Lines 文件路径加载记录。"""
    with open(path, "r", encoding="utf-8") as fh:
        return load_lines(fh)

"""查询、游标分页与聚合统计引擎。

筛选条件（不同条件之间取交集，均可省略）：
- ``address``：精确匹配 from_address 或 to_address（不可与
  ``from_address`` / ``to_address`` 并用）
- ``from_address`` / ``to_address`` / ``method``：值集合，集合内部
  任一命中即可；可重复给定，重复值等同一个条件
- ``start_time`` / ``end_time``：时间窗，左闭右闭（UTC 秒）

排序：block_number 升序，同高度按 tx_hash 升序。
分页：不透明 keyset 游标（见 :mod:`tx_indexer.cursor`），相同筛选下
不跳过、不重复、不乱序；``total`` 始终为全部匹配数。
"""

import bisect

from .cursor import decode_cursor, encode_cursor
from .errors import (
    InvalidFilterError,
    InvalidPageSizeError,
    InvalidTimeRangeError,
)

DEFAULT_PAGE_SIZE = 100
MAX_PAGE_SIZE = 1000

_PUBLIC_FIELDS = (
    "tx_hash",
    "block_number",
    "timestamp",
    "from_address",
    "to_address",
    "method",
    "amount",
)


def _normalize_value_set(name, values):
    """把单个值或值迭代器归一化为去重后的 frozenset；空集合返回 None。"""
    if values is None:
        return None
    if isinstance(values, str):
        values = (values,)
    result = set()
    for value in values:
        if not isinstance(value, str) or value.strip() == "":
            raise InvalidFilterError(
                "%s 筛选值不能为空或仅含空白" % name, None
            )
        result.add(value)
    if not result:
        return None
    return frozenset(result)


def normalize_filters(address=None, method=None, start_time=None, end_time=None,
                      from_address=None, to_address=None):
    """校验并归一化筛选条件。

    ``method`` / ``from_address`` / ``to_address`` 接受单个字符串或
    字符串迭代器，归一化为去重集合（frozenset）；不给或为空则为 None。
    """
    if address is not None and (
        not isinstance(address, str) or address.strip() == ""
    ):
        raise InvalidFilterError(
            "address 筛选值不能为空或仅含空白", None
        )
    from_set = _normalize_value_set("from_address", from_address)
    to_set = _normalize_value_set("to_address", to_address)
    method_set = _normalize_value_set("method", method)
    if address is not None and (from_set is not None or to_set is not None):
        raise InvalidFilterError(
            "address 不能与 from_address / to_address 同时使用", None
        )
    for name, value in (("start_time", start_time), ("end_time", end_time)):
        if value is not None and (
            not isinstance(value, int) or isinstance(value, bool) or value < 0
        ):
            raise ValueError("%s 必须为非负整数" % name)
    if start_time is not None and end_time is not None and start_time > end_time:
        raise InvalidTimeRangeError(
            "时间窗倒置：start_time(%d) 大于 end_time(%d)"
            % (start_time, end_time),
            None,
        )
    return {
        "address": address,
        "from_address": from_set,
        "to_address": to_set,
        "method": method_set,
        "start_time": start_time,
        "end_time": end_time,
    }


def _matches(record, filters):
    if filters["address"] is not None:
        addr = filters["address"]
        if record["from_address"] != addr and record["to_address"] != addr:
            return False
    if (
        filters["from_address"] is not None
        and record["from_address"] not in filters["from_address"]
    ):
        return False
    if (
        filters["to_address"] is not None
        and record["to_address"] not in filters["to_address"]
    ):
        return False
    if (
        filters["method"] is not None
        and record["method"] not in filters["method"]
    ):
        return False
    ts = record["timestamp"]
    if filters["start_time"] is not None and ts < filters["start_time"]:
        return False
    if filters["end_time"] is not None and ts > filters["end_time"]:
        return False
    return True


def to_public(record):
    """按公开字段顺序输出一条交易。"""
    return {name: record[name] for name in _PUBLIC_FIELDS}


class TxIndexer:
    """内存中的交易索引（无额外持久化）。"""

    def __init__(self, records):
        # 加载顺序保留；查询时统一排序，不修改入参列表语义
        self._records = list(records)

    def _matched(self, filters):
        matched = [r for r in self._records if _matches(r, filters)]
        matched.sort(key=lambda r: (r["block_number"], r["tx_hash"]))
        return matched

    @staticmethod
    def _validate_page_size(page_size):
        if (
            not isinstance(page_size, int)
            or isinstance(page_size, bool)
            or page_size < 1
            or page_size > MAX_PAGE_SIZE
        ):
            raise InvalidPageSizeError(
                "page_size 必须为 1 到 %d 之间的整数（默认 %d）"
                % (MAX_PAGE_SIZE, DEFAULT_PAGE_SIZE),
                None,
            )

    def query(self, filters, page_size=DEFAULT_PAGE_SIZE, cursor=None):
        """分页查询。返回 {transactions, total, next_cursor}。"""
        self._validate_page_size(page_size)

        matched = self._matched(filters)
        total = len(matched)

        start = 0
        if cursor is not None:
            after_block, after_tx_hash = decode_cursor(cursor, filters)
            # keyset 续页：排序键严格大于 marker 的第一个位置。
            # marker 位于两键之间也安全（bisect 取下一键），不会跳过或重复。
            keys = [(r["block_number"], r["tx_hash"]) for r in matched]
            start = bisect.bisect_left(keys, (after_block, after_tx_hash))
            if start < total and keys[start] == (after_block, after_tx_hash):
                # marker 命中现存记录本身：从其后一条开始
                start += 1

        end = start + page_size
        page = matched[start:end]
        if end < total:
            last = page[-1]
            next_cursor = encode_cursor(
                filters, last["block_number"], last["tx_hash"]
            )
        else:
            next_cursor = None

        return {
            "transactions": [to_public(r) for r in page],
            "total": total,
            "next_cursor": next_cursor,
        }

    def stats(self, filters):
        """聚合统计（忽略分页）。"""
        total_amount = 0
        min_amount = None
        max_amount = None
        count = 0
        for record in self._records:
            if not _matches(record, filters):
                continue
            value = int(record["amount"])
            count += 1
            total_amount += value
            if min_amount is None or value < min_amount:
                min_amount = value
            if max_amount is None or value > max_amount:
                max_amount = value

        if count == 0:
            return {
                "total_count": 0,
                "total_amount": "0",
                "min_amount": None,
                "max_amount": None,
                "avg_amount": None,
            }
        return {
            "total_count": count,
            "total_amount": str(total_amount),
            "min_amount": str(min_amount),
            "max_amount": str(max_amount),
            "avg_amount": str(total_amount // count),
        }

"""不透明分页游标。

游标为自包含令牌：base64url 编码的 JSON，记录签发时的完整筛选条件与
本页最后一条记录的排序键 ``(block_number, tx_hash)``（exclusive marker）。

- 格式错误、无法解码或字段非法 → InvalidCursorError
- 游标内筛选与当前请求筛选不一致 → InvalidCursorError

筛选快照中集合类条件（from_address / to_address / method）统一存为
排序后的列表；解码比较时同样归一化，因此旧版游标（method 为单个字符串、
无集合字段）在筛选等价时仍可续页。
"""

import base64
import binascii
import json

from .errors import InvalidCursorError

_CURSOR_VERSION = 1


def _as_sorted_list(value):
    """集合类筛选的规范形：None → None，单字符串 → [值]，其余 → 排序列表。"""
    if value is None:
        return None
    if isinstance(value, str):
        return [value]
    return sorted(value)


def _canonical_filters(filters):
    """提取用于游标绑定比对的筛选快照（集合归一化为排序列表）。"""
    return {
        "address": filters.get("address"),
        "from_address": _as_sorted_list(filters.get("from_address")),
        "to_address": _as_sorted_list(filters.get("to_address")),
        "method": _as_sorted_list(filters.get("method")),
        "start_time": filters.get("start_time"),
        "end_time": filters.get("end_time"),
    }


def encode_cursor(filters, after_block, after_tx_hash):
    payload = {
        "v": _CURSOR_VERSION,
        "f": _canonical_filters(filters),
        "after": [after_block, after_tx_hash],
    }
    raw = json.dumps(payload, separators=(",", ":"), sort_keys=True).encode("utf-8")
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")


def _b64url_decode(token):
    try:
        padding = "=" * (-len(token) % 4)
        return base64.urlsafe_b64decode(token + padding)
    except (ValueError, binascii.Error) as exc:
        raise InvalidCursorError("游标编码非法", None) from exc


def decode_cursor(token, filters):
    """解码并校验游标，返回 exclusive marker ``(block_number, tx_hash)``。"""
    if not isinstance(token, str) or token == "":
        raise InvalidCursorError("游标为空或类型非法", None)

    raw = _b64url_decode(token)
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise InvalidCursorError("游标内容非法", None) from exc

    if not isinstance(payload, dict) or payload.get("v") != _CURSOR_VERSION:
        raise InvalidCursorError("游标版本不受支持", None)

    saved = payload.get("f")
    if not isinstance(saved, dict):
        raise InvalidCursorError("游标缺少筛选信息", None)

    try:
        saved_canonical = _canonical_filters(saved)
        current_canonical = _canonical_filters(filters)
    except (TypeError, ValueError) as exc:
        raise InvalidCursorError("游标筛选信息非法", None) from exc
    if saved_canonical != current_canonical:
        raise InvalidCursorError("游标与当前筛选条件不匹配", None)

    after = payload.get("after")
    if (
        not isinstance(after, list)
        or len(after) != 2
        or not isinstance(after[0], int)
        or isinstance(after[0], bool)
        or after[0] < 0
        or not isinstance(after[1], str)
        or after[1] == ""
    ):
        raise InvalidCursorError("游标位置信息非法", None)

    return after[0], after[1]

